import { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function QuizPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const domain = searchParams.get('domain') || 'web-development';
  
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchQuestions = async () => {
      setLoading(true);
      try {
        const res = await fetch("http://localhost:5000/api/quiz/generate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ domain })
        });
        const data = await res.json();
        setQuestions(data);
      } catch (err) {
        console.error("Failed to load questions", err);
      } finally {
        setLoading(false);
      }
    };
    fetchQuestions();
  }, [domain]);

  const score = questions.reduce((acc, q, idx) => 
    acc + (selected[idx] === q.answer ? 1 : 0), 0
  );

  if (loading) return (
    <div className="flex flex-col items-center justify-center p-20">
      <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mb-4"></div>
      <p className="text-slate-600">Generating unique questions for {domain}...</p>
    </div>
  );

  return (
    <div className="max-w-4xl mx-auto p-4 space-y-6">
      <div className="bg-white rounded-3xl p-8 border shadow-sm">
        <h2 className="text-2xl font-bold capitalize mb-6">{domain.replace(/-/g, ' ')} Quiz</h2>
        
        <div className="space-y-8">
          {questions.map((q, idx) => (
            <div key={idx} className="p-6 rounded-2xl bg-slate-50 border">
              <p className="font-semibold text-lg mb-4">{idx + 1}. {q.question}</p>
              <div className="grid gap-3 sm:grid-cols-2">
                {q.options.map((opt) => (
                  <button
                    key={opt}
                    disabled={submitted}
                    onClick={() => setSelected(prev => ({ ...prev, [idx]: opt }))}
                    className={`p-4 text-left border rounded-xl transition-all ${
                      selected[idx] === opt ? 'bg-blue-600 text-white border-blue-600' : 'bg-white hover:border-blue-300'
                    } ${submitted && opt === q.answer ? 'ring-2 ring-green-500' : ''}`}
                  >
                    {opt}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div className="mt-8 border-t pt-6">
          {!submitted ? (
            <Button onClick={() => setSubmitted(true)} disabled={Object.keys(selected).length < questions.length}>
              Submit Quiz
            </Button>
          ) : (
            <div className="flex items-center justify-between">
              <span className="text-xl font-bold text-green-600">Score: {score}/{questions.length}</span>
              <Button onClick={() => navigate(`/roadmap/${domain}`)}>Continue to Roadmap</Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
